package ai.flownova;

import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.JsonNode;

@Service
class WorkflowService {
    final JdbcTemplate db; final Graphs graphs;
    WorkflowService(JdbcTemplate db, Graphs graphs){this.db=db;this.graphs=graphs;}
    JdbcTemplate jdbc(){return db;}
    record Workspace(String id,String name,String role){}
    record Workflow(String id,String workspaceId,String name,String description,JsonNode graph,int revision,int publishedVersion,long updatedAt){}
    record Execution(String id,String workflowId,String workflowName,int version,String status,long createdAt,Long startedAt,Long finishedAt,String error){}
    record Save(String name,String description,JsonNode graph,int revision){}
    static String id(){return UUID.randomUUID().toString();}
    static ResponseStatusException fail(HttpStatus status,String message){return new ResponseStatusException(status,message);}
    String access(String actor,String workspace,boolean write){
        var roles=db.query("SELECT role FROM membership WHERE actor=? AND workspace_id=?",(r,i)->r.getString(1),actor,workspace);
        if(roles.isEmpty())throw fail(HttpStatus.NOT_FOUND,"Workspace not found");
        if(write&&roles.getFirst().equals("VIEWER"))throw fail(HttpStatus.FORBIDDEN,"Editor access is required");
        return roles.getFirst();
    }
    List<Workspace> workspaces(String actor){return db.query("SELECT w.id,w.name,m.role FROM workspace w JOIN membership m ON m.workspace_id=w.id WHERE m.actor=? ORDER BY w.name",(r,i)->new Workspace(r.getString(1),r.getString(2),r.getString(3)),actor);}
    Workflow map(java.sql.ResultSet r) throws java.sql.SQLException{return new Workflow(r.getString("id"),r.getString("workspace_id"),r.getString("name"),r.getString("description"),graphs.parse(r.getString("graph")),r.getInt("revision"),r.getInt("published_version"),r.getLong("updated_at"));}
    List<Workflow> list(String actor,String w,int limit,int offset){access(actor,w,false);return db.query("SELECT * FROM workflow WHERE workspace_id=? ORDER BY updated_at DESC LIMIT ? OFFSET ?",(r,i)->map(r),w,limit,offset);}
    Workflow get(String actor,String w,String workflow){access(actor,w,false);var rows=db.query("SELECT * FROM workflow WHERE id=? AND workspace_id=?",(r,i)->map(r),workflow,w);if(rows.isEmpty())throw fail(HttpStatus.NOT_FOUND,"Workflow not found");return rows.getFirst();}
    void checkSave(Save s){if(s==null||s.name()==null||s.name().isBlank()||s.name().length()>100||s.description()==null||s.description().length()>500||s.graph()==null||graphs.stringify(s.graph()).length()>131072)throw fail(HttpStatus.BAD_REQUEST,"Name, description or graph exceeds allowed limits");if(!s.graph().path("nodes").isArray()||!s.graph().path("edges").isArray()||s.graph().path("nodes").size()>50||s.graph().path("edges").size()>100)throw fail(HttpStatus.BAD_REQUEST,"Draft must contain at most 50 nodes and 100 edges");}
    @Transactional
    Workflow create(String actor,String w,Save s){access(actor,w,true);checkSave(s);if(db.queryForObject("SELECT COUNT(*) FROM workflow WHERE workspace_id=?",Integer.class,w)>=100)throw fail(HttpStatus.TOO_MANY_REQUESTS,"Workspace workflow limit reached");String id=id();db.update("INSERT INTO workflow(id,workspace_id,name,description,graph,revision,published_version,updated_at,updated_by) VALUES (?,?,?,?,?,1,0,?,?)",id,w,s.name().trim(),s.description(),graphs.stringify(s.graph()),System.currentTimeMillis(),actor);audit(actor,w,"WORKFLOW_CREATED",id);return get(actor,w,id);}
    @Transactional
    Workflow save(String actor,String w,String id,Save s){access(actor,w,true);checkSave(s);get(actor,w,id);int updated=db.update("UPDATE workflow SET name=?,description=?,graph=?,revision=revision+1,updated_at=?,updated_by=? WHERE id=? AND workspace_id=? AND revision=?",s.name().trim(),s.description(),graphs.stringify(s.graph()),System.currentTimeMillis(),actor,id,w,s.revision());if(updated!=1)throw fail(HttpStatus.CONFLICT,"This draft changed elsewhere. Reload before saving.");audit(actor,w,"DRAFT_SAVED",id);return get(actor,w,id);}
    @Transactional
    Workflow publish(String actor,String w,String id,int revision){access(actor,w,true);db.queryForList("SELECT id FROM workflow WHERE id=? AND workspace_id=? FOR UPDATE",id,w);var f=get(actor,w,id);if(f.revision()!=revision)throw fail(HttpStatus.CONFLICT,"Draft revision changed. Reload before publishing.");var issues=graphs.validate(f.graph());if(!issues.isEmpty())throw fail(HttpStatus.UNPROCESSABLE_ENTITY,issues.getFirst().message());int version=f.publishedVersion()+1;db.update("INSERT INTO workflow_version VALUES (?,?,?,?,?,?)",id,w,version,graphs.stringify(f.graph()),System.currentTimeMillis(),actor);db.update("UPDATE workflow SET published_version=? WHERE id=? AND workspace_id=?",version,id,w);audit(actor,w,"WORKFLOW_PUBLISHED",id);return get(actor,w,id);}
    List<Map<String,Object>> versions(String actor,String w,String id){get(actor,w,id);return db.query("SELECT version,created_at,created_by FROM workflow_version WHERE workflow_id=? AND workspace_id=? ORDER BY version DESC",(r,i)->Map.of("version",r.getInt(1),"createdAt",r.getLong(2),"createdBy",r.getString(3)),id,w);}
    JsonNode version(String actor,String w,String id,int version){get(actor,w,id);var rows=db.query("SELECT graph FROM workflow_version WHERE workflow_id=? AND workspace_id=? AND version=?",(r,i)->graphs.parse(r.getString(1)),id,w,version);if(rows.isEmpty())throw fail(HttpStatus.NOT_FOUND,"Published version not found");return rows.getFirst();}
    @Transactional
    Workflow restore(String actor,String w,String id,int version,int revision){access(actor,w,true);var f=get(actor,w,id);var restored=save(actor,w,id,new Save(f.name(),f.description(),version(actor,w,id,version),revision));audit(actor,w,"VERSION_RESTORED_TO_DRAFT",id);return restored;}
    @Transactional
    Execution execute(String actor,String w,String id,JsonNode input,String key){access(actor,w,true);if(key==null||!key.matches("[a-zA-Z0-9_-]{1,100}"))throw fail(HttpStatus.BAD_REQUEST,"Supply a unique Idempotency-Key (1–100 characters)");if(input==null||!input.isObject()||graphs.stringify(input).length()>16384)throw fail(HttpStatus.BAD_REQUEST,"Execution input must be an object up to 16 KB");db.queryForList("SELECT id FROM workspace WHERE id=? FOR UPDATE",w);var f=get(actor,w,id);var existing=db.queryForList("SELECT id,workflow_id FROM execution WHERE workspace_id=? AND idempotency_key=?",w,key);if(!existing.isEmpty()){if(!existing.getFirst().get("workflow_id").equals(id))throw fail(HttpStatus.CONFLICT,"Idempotency key belongs to another workflow");return execution(actor,w,(String)existing.getFirst().get("id"));}if(f.publishedVersion()==0)throw fail(HttpStatus.CONFLICT,"Publish a validated version first");if(db.queryForObject("SELECT COUNT(*) FROM execution WHERE workspace_id=? AND created_at>?",Integer.class,w,System.currentTimeMillis()-3600000)>=100)throw fail(HttpStatus.TOO_MANY_REQUESTS,"Local limit: 100 executions per hour");String run=id();db.update("INSERT INTO execution(id,workspace_id,workflow_id,version,status,input,created_at,created_by,idempotency_key) VALUES (?,?,?,?,'QUEUED',?,?,?,?)",run,w,id,f.publishedVersion(),graphs.stringify(graphs.redact(input)),System.currentTimeMillis(),actor,key);event(run,null,"QUEUED","Execution queued");audit(actor,w,"EXECUTION_STARTED",run);return execution(actor,w,run);}
    Execution mapExecution(java.sql.ResultSet r)throws java.sql.SQLException{return new Execution(r.getString("id"),r.getString("workflow_id"),r.getString("workflow_name"),r.getInt("version"),r.getString("status"),r.getLong("created_at"),(Long)r.getObject("started_at"),(Long)r.getObject("finished_at"),r.getString("error"));}
    List<Execution> executions(String actor,String w,int limit,int offset){access(actor,w,false);return db.query("SELECT e.*,f.name AS workflow_name FROM execution e JOIN workflow f ON f.id=e.workflow_id WHERE e.workspace_id=? ORDER BY e.created_at DESC LIMIT ? OFFSET ?",(r,i)->mapExecution(r),w,limit,offset);}
    Execution execution(String actor,String w,String id){access(actor,w,false);var list=db.query("SELECT e.*,f.name AS workflow_name FROM execution e JOIN workflow f ON f.id=e.workflow_id WHERE e.id=? AND e.workspace_id=?",(r,i)->mapExecution(r),id,w);if(list.isEmpty())throw fail(HttpStatus.NOT_FOUND,"Execution not found");return list.getFirst();}
    Map<String,Object> detail(String actor,String w,String id){var run=execution(actor,w,id);var nodes=db.query("SELECT * FROM node_execution WHERE execution_id=? ORDER BY started_at,node_id",(r,i)->Map.of("nodeId",r.getString("node_id"),"status",r.getString("status"),"output",graphs.parse(r.getString("output")),"startedAt",r.getLong("started_at"),"finishedAt",r.getLong("finished_at")),id);var events=db.query("SELECT * FROM execution_event WHERE execution_id=? ORDER BY created_at,id",(r,i)->Map.of("id",r.getString("id"),"kind",r.getString("kind"),"nodeId",Objects.toString(r.getString("node_id"),""),"message",r.getString("message"),"createdAt",r.getLong("created_at")),id);return Map.of("execution",run,"nodes",nodes,"events",events);}
    @Transactional
    void cancel(String actor,String w,String id){access(actor,w,true);execution(actor,w,id);if(db.update("UPDATE execution SET status='CANCELLED',finished_at=?,lease_until=NULL WHERE id=? AND workspace_id=? AND status IN ('QUEUED','RUNNING')",System.currentTimeMillis(),id,w)!=1)throw fail(HttpStatus.CONFLICT,"Execution is already finished");event(id,null,"CANCELLED","Cancellation requested by workspace member");audit(actor,w,"EXECUTION_CANCELLED",id);}
    Map<String,Object> analytics(String actor,String w){access(actor,w,false);var counts=db.queryForList("SELECT status,COUNT(*) AS total FROM execution WHERE workspace_id=? GROUP BY status",w);long total=0,success=0,failed=0;for(var r:counts){long n=((Number)r.get("total")).longValue();total+=n;if(r.get("status").equals("SUCCEEDED"))success+=n;if(Set.of("FAILED","TIMED_OUT").contains(r.get("status")))failed+=n;}return Map.of("workflows",db.queryForObject("SELECT COUNT(*) FROM workflow WHERE workspace_id=?",Long.class,w),"published",db.queryForObject("SELECT COUNT(*) FROM workflow WHERE workspace_id=? AND published_version>0",Long.class,w),"executions",total,"succeeded",success,"failed",failed,"successRate",total==0?0:Math.round(success*100.0/total));}
    void event(String run,String node,String kind,String message){db.update("INSERT INTO execution_event VALUES (?,?,?,?,?,?)",id(),run,System.currentTimeMillis(),node,kind,message);}
    void audit(String actor,String w,String action,String resource){db.update("INSERT INTO audit_log VALUES (?,?,?,?,?,?)",id(),w,actor,action,resource,System.currentTimeMillis());}
}
